#include <bits/stdc++.h>
using namespace std;
int main(){for(int m=2;m<=6;m++){int n=2*m; size_t N=1ULL<<(2*n);vector<int> to(N), indeg(N), dep(N,-1), period(N,0);for(size_t s=0;s<N;s++){int cnt=0;for(int v=0;v<n;v++)cnt+=((s>>(2*v))&3)==1;unsigned long long y=0;for(int v=0;v<n;v++){int a=(s>>(2*v))&3,b=(s>>(2*(v^1)))&3;int next=a==0?(cnt-(b==1)>=1):((a+1)&3);y|=(unsigned long long)next<<(2*v);}to[s]=y;indeg[y]++;}vector<int> order;order.reserve(N);queue<int> q;for(size_t s=0;s<N;s++)if(!indeg[s])q.push(s);while(!q.empty()){int x=q.front();q.pop();order.push_back(x);if(!--indeg[to[x]])q.push(to[x]);}map<int,long long> cycles,states,depthmax;int maxd=0;for(size_t s=0;s<N;s++)if(indeg[s]&&period[s]==0){int t=s,k=0;do{t=to[t];k++;}while(t!=(int)s);t=s;do{period[t]=k;dep[t]=0;t=to[t];}while(t!=(int)s);cycles[k]++;}for(int i=(int)order.size()-1;i>=0;i--){int x=order[i];period[x]=period[to[x]];dep[x]=dep[to[x]]+1;}for(size_t s=0;s<N;s++){states[period[s]]++;depthmax[dep[s]]++;maxd=max(maxd,dep[s]);}cerr<<"m="<<m<<" max="<<maxd<<" cycles:";for(auto [k,v]:cycles)cerr<<' '<<k<<':'<<v;cerr<<" periodic states:";for(auto [k,v]:states)cerr<<' '<<k<<':'<<v;cerr<<" maxattain="<<depthmax[maxd]<<"\n";}}
